edits.replacement:
// v16.xx (cw-gearrules): the gun keys are 1 to 8 and 0 (GUN_CLASSES: a key for each kind of gun, the rocket launcher on 0; key 9 does nothing). Said short, lower case.
['WEAPONS','keys 1 to 8 and 0 bring up'],
['','your guns, a key for each kind.'],

check:
{v:'VER',what:'cw-gearrules: the controls tips say the gun keys as they are now (1 to 8 and 0, a key for each kind of gun, read from GUN_CLASSES and slotKeyName), in lower case, and no tip still teaches keys 1 to 4, 5-6 throw, 7-8 heal, 9 plate or the G, H, U, J keys',
 run:function(){
   if(typeof GEARRULES==='undefined'||!GEARRULES.length) return 'SKIP: no controls tips in this build';
   if(typeof GUN_CLASSES==='undefined'||typeof slotKeyName!=='function'||typeof slotKeyCode!=='function') return 'SKIP: no gun key table in this build';
   var bad=[], i, j, k, row=-1, txt='', all='', t, n=GUN_CLASSES.length, want, codes=[];
   for(i=0;i<GEARRULES.length;i++){ t=(typeof GEARRULES[i][1]==='function')?String(GEARRULES[i][1]()):String(GEARRULES[i][1]); all+=' | '+t; if(row<0&&GEARRULES[i][0]==='WEAPONS') row=i; }
   if(row<0) return 'SKIP: the tips have no WEAPONS rule';
   for(i=row;i<=row+1&&i<GEARRULES.length;i++) txt+=((typeof GEARRULES[i][1]==='function')?String(GEARRULES[i][1]()):String(GEARRULES[i][1]))+' ';   // the WEAPONS line and the one under it
   // the keys the game really gives the guns: one key a kind of gun, 1 to 8 and then 0
   for(k=0;k<n;k++) codes.push(slotKeyCode(k));
   if(codes.indexOf('Digit9')>=0) bad.push('ZERO: key 9 is a gun key now, so the tips below need another look');
   want='keys '+slotKeyName(0)+' to '+slotKeyName(n-2)+' and '+slotKeyName(n-1);
   if(txt.toLowerCase().indexOf(want)<0) bad.push('ONE: the WEAPONS tip does not say ['+want+'] (it says ['+txt.trim()+'])');
   if(/\b1 to 4\b|\b1-4\b|four gun/i.test(txt)) bad.push('TWO: the WEAPONS tip still says keys 1 to 4 ['+txt.trim()+']');
   if(txt!==txt.toLowerCase()) bad.push('THREE: the WEAPONS tip is not lower case ['+txt.trim()+']');
   if(/\b5-6\b|\b7-8\b|9 plate|\bG, H\b|\bU, J\b|pick the next|Gun stays in hand/.test(all)) bad.push('FOUR: a tip still teaches the retired belt keys ['+all.match(/\b5-6\b|\b7-8\b|9 plate|\bG, H\b|\bU, J\b|pick the next|Gun stays in hand/)[0]+']');
   return bad.length?bad.join('; '):null; }},
